// Basic match
let classify n =
    match n with
    | 0 -> "zero"
    | n when n > 0 -> "positive"
    | _ -> "negative"

// List matching
let rec sumList lst =
    match lst with
    | [] -> 0
    | head :: tail -> head + sumList tail

// Option matching
match divideOpt 10 2 with
| Some result -> printfn "Result: %d" result
| None -> printfn "Division by zero"

// Tuple matching
let describe_pair pair =
    match pair with
    | (0, 0) -> "origin"
    | (x, 0) -> sprintf "on x-axis at %d" x
    | (x, y) -> sprintf "at (%d, %d)" x y

// Active patterns
let (|Even|Odd|) n =
    if n % 2 = 0 then Even else Odd

match 42 with
| Even -> "even"
| Odd  -> "odd"
